1	package auth
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"runtime"
9		"strings"
10	)
11	
12	const fileStoreVersion = 1
13	
14	type fileStoreData struct {
15		Version int               `json:"version"`
16		Tokens  map[string]string `json:"tokens"`
17	}
18	
19	func configuredSecretsPath() (string, bool, error) {
20		raw := strings.TrimSpace(os.Getenv(SecretsPathEnvVar))
21		if raw == "" {
22			return "", false, nil
23		}
24	
25		path, err := expandHome(raw)
26		if err != nil {
27			return "", false, err
28		}
29		path = filepath.Clean(path)
30		if !filepath.IsAbs(path) {
31			return "", false, fmt.Errorf("%s must be an absolute path after ~/ expansion", SecretsPathEnvVar)
32		}
33	
34		return path, true, nil
35	}
36	
37	func expandHome(path string) (string, error) {
38		if path == "~" {
39			home, err := os.UserHomeDir()
40			if err != nil {
41				return "", fmt.Errorf("resolve home directory: %w", err)
42			}
43			return home, nil
44		}
45		if strings.HasPrefix(path, "~/") {
46			home, err := os.UserHomeDir()
47			if err != nil {
48				return "", fmt.Errorf("resolve home directory: %w", err)
49			}
50			return filepath.Join(home, strings.TrimPrefix(path, "~/")), nil
51		}
52		return path, nil
53	}
54	
55	func readFileStore(path string) (fileStoreData, error) {
56		info, err := os.Stat(path)
57		if os.IsNotExist(err) {
58			return newFileStoreData(), nil
59		}
60		if err != nil {
61			return fileStoreData{}, fmt.Errorf("stat token file: %w", err)
62		}
63		if info.IsDir() {
64			return fileStoreData{}, fmt.Errorf("token file path is a directory: %s", path)
65		}
66		if runtime.GOOS != "windows" && info.Mode().Perm()&0o077 != 0 {
67			return fileStoreData{}, fmt.Errorf("token file %s has unsafe permissions %o; run chmod 600 %s", path, info.Mode().Perm(), path)
68		}
69	
70		data, err := os.ReadFile(path) //nolint:gosec // path is explicit user-provided credential path.
71		if err != nil {
72			return fileStoreData{}, fmt.Errorf("read token file: %w", err)
73		}
74		if len(strings.TrimSpace(string(data))) == 0 {
75			return newFileStoreData(), nil
76		}
77	
78		var store fileStoreData
79		if err := json.Unmarshal(data, &store); err != nil {
80			return fileStoreData{}, fmt.Errorf("parse token file: %w", err)
81		}
82		if store.Version == 0 {
83			store.Version = fileStoreVersion
84		}
85		if store.Version != fileStoreVersion {
86			return fileStoreData{}, fmt.Errorf("unsupported token file version %d", store.Version)
87		}
88		if store.Tokens == nil {
89			store.Tokens = make(map[string]string)
90		}
91	
92		return store, nil
93	}
94	
95	func writeFileStore(path string, store fileStoreData) error {
96		if store.Version == 0 {
97			store.Version = fileStoreVersion
98		}
99		if store.Tokens == nil {
100			store.Tokens = make(map[string]string)
101		}
102	
103		dir := filepath.Dir(path)
104		if err := os.MkdirAll(dir, 0o700); err != nil {
105			return fmt.Errorf("create token file directory: %w", err)
106		}
107	
108		temp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".tmp-*")
109		if err != nil {
110			return fmt.Errorf("create temporary token file: %w", err)
111		}
112		tempName := temp.Name()
113		defer func() { _ = os.Remove(tempName) }()
114	
115		if err := temp.Chmod(0o600); err != nil {
116			_ = temp.Close()
117			return fmt.Errorf("set temporary token file permissions: %w", err)
118		}
119	
120		enc := json.NewEncoder(temp)
121		enc.SetIndent("", "  ")
122		if err := enc.Encode(store); err != nil {
123			_ = temp.Close()
124			return fmt.Errorf("write token file JSON: %w", err)
125		}
126		if err := temp.Close(); err != nil {
127			return fmt.Errorf("close temporary token file: %w", err)
128		}
129	
130		if err := os.Rename(tempName, path); err != nil {
131			return fmt.Errorf("replace token file: %w", err)
132		}
133		if runtime.GOOS != "windows" {
134			if err := os.Chmod(path, 0o600); err != nil {
135				return fmt.Errorf("set token file permissions: %w", err)
136			}
137		}
138	
139		return nil
140	}
141	
142	func newFileStoreData() fileStoreData {
143		return fileStoreData{
144			Version: fileStoreVersion,
145			Tokens:  make(map[string]string),
146		}
147	}
148	
149	func getFileToken(path, baseURL string) (string, error) {
150		store, err := readFileStore(path)
151		if err != nil {
152			return "", err
153		}
154		return store.Tokens[baseURL], nil
155	}
156	
157	func saveFileToken(path, baseURL, token string) error {
158		store, err := readFileStore(path)
159		if err != nil {
160			return err
161		}
162		store.Tokens[baseURL] = token
163		if err := writeFileStore(path, store); err != nil {
164			return err
165		}
166		return nil
167	}
168	
169	func deleteFileToken(path, baseURL string) error {
170		if _, err := os.Stat(path); os.IsNotExist(err) {
171			return nil
172		} else if err != nil {
173			return fmt.Errorf("stat token file: %w", err)
174		}
175	
176		store, err := readFileStore(path)
177		if err != nil {
178			return err
179		}
180		if _, ok := store.Tokens[baseURL]; !ok {
181			return nil
182		}
183		delete(store.Tokens, baseURL)
184		if err := writeFileStore(path, store); err != nil {
185			return err
186		}
187		return nil
188	}
