1	package auth
2	
3	import (
4		"errors"
5		"fmt"
6		"strings"
7	
8		"github.com/entireio/cli/cmd/entire/cli/api"
9		"github.com/zalando/go-keyring"
10	)
11	
12	const keyringService = "entire-cli"
13	
14	// Store manages CLI authentication tokens across the configured auth sources.
15	type Store struct {
16		service string
17	}
18	
19	// NewStore returns a Store using the default keyring service when no file store is configured.
20	func NewStore() *Store {
21		return &Store{service: keyringService}
22	}
23	
24	// NewStoreWithService returns a Store with a custom keyring service name (for testing).
25	func NewStoreWithService(service string) *Store {
26		return &Store{service: service}
27	}
28	
29	// SaveToken persists an access token for the given base URL.
30	func (s *Store) SaveToken(baseURL, token string) error {
31		token = strings.TrimSpace(token)
32		if token == "" {
33			return errors.New("refusing to save empty token")
34		}
35	
36		if path, ok, err := configuredSecretsPath(); err != nil {
37			return err
38		} else if ok {
39			if err := saveFileToken(path, baseURL, token); err != nil {
40				return fmt.Errorf("save token to file: %w", err)
41			}
42			return nil
43		}
44	
45		if err := keyring.Set(s.service, baseURL, token); err != nil {
46			return fmt.Errorf("save token to keyring: %w", err)
47		}
48	
49		return nil
50	}
51	
52	// GetToken retrieves a stored token for the given base URL.
53	// Returns an empty string (and no error) if no token is stored.
54	func (s *Store) GetToken(baseURL string) (string, error) {
55		info, err := s.GetTokenInfo(baseURL)
56		if err != nil {
57			return "", err
58		}
59	
60		return info.Value, nil
61	}
62	
63	// GetTokenInfo retrieves a stored token and reports where it came from.
64	// Returns an empty TokenInfo (and no error) if no token is stored.
65	func (s *Store) GetTokenInfo(baseURL string) (TokenInfo, error) {
66		if token := envAuthToken(); token != "" {
67			return TokenInfo{Value: token, Source: TokenSourceEnv}, nil
68		}
69	
70		if path, ok, err := configuredSecretsPath(); err != nil {
71			return TokenInfo{}, err
72		} else if ok {
73			token, err := getFileToken(path, baseURL)
74			if err != nil {
75				return TokenInfo{}, fmt.Errorf("get token from file: %w", err)
76			}
77			if token == "" {
78				return TokenInfo{}, nil
79			}
80			return TokenInfo{Value: token, Source: TokenSourceFile, Path: path}, nil
81		}
82	
83		token, err := keyring.Get(s.service, baseURL)
84		if errors.Is(err, keyring.ErrNotFound) {
85			return TokenInfo{}, nil
86		}
87		if err != nil {
88			return TokenInfo{}, fmt.Errorf("get token from keyring: %w", err)
89		}
90	
91		return TokenInfo{Value: token, Source: TokenSourceKeyring}, nil
92	}
93	
94	// DeleteToken removes a stored token for the given base URL.
95	func (s *Store) DeleteToken(baseURL string) error {
96		if path, ok, err := configuredSecretsPath(); err != nil {
97			return err
98		} else if ok {
99			if err := deleteFileToken(path, baseURL); err != nil {
100				return fmt.Errorf("delete token from file: %w", err)
101			}
102			return nil
103		}
104	
105		err := keyring.Delete(s.service, baseURL)
106		if errors.Is(err, keyring.ErrNotFound) {
107			return nil
108		}
109		if err != nil {
110			return fmt.Errorf("delete token from keyring: %w", err)
111		}
112	
113		return nil
114	}
115	
116	// LookupCurrentToken retrieves the token for the current base URL.
117	func LookupCurrentToken() (string, error) {
118		store := NewStore()
119		return store.GetToken(api.BaseURL())
120	}
