1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"sort"
11		"strings"
12		"time"
13	
14		"charm.land/lipgloss/v2"
15		"github.com/entireio/cli/cmd/entire/cli/api"
16		"github.com/entireio/cli/cmd/entire/cli/auth"
17		"github.com/spf13/cobra"
18	)
19	
20	// authTokenLister lists API tokens for the authenticated user.
21	type authTokenLister func(ctx context.Context, token string) ([]api.Token, error)
22	
23	// authTokenRevoker revokes a single API token by id.
24	type authTokenRevoker func(ctx context.Context, callerToken, id string) error
25	
26	// User-visible placeholder strings. Promoted to constants so tests and
27	// production share a single source of truth.
28	const (
29		placeholderDash = "-"
30		lastUsedNever   = "never"
31		lastUsedJustNow = "just now"
32	)
33	
34	// requireSecureBaseURL enforces TLS unless insecureHTTPAuth is set. Every
35	// command that sends a bearer token over the network (login, logout,
36	// auth status/list/revoke) must call this so credentials don't leak over
37	// plaintext HTTP without explicit opt-in.
38	func requireSecureBaseURL(insecureHTTPAuth bool) error {
39		if insecureHTTPAuth {
40			return nil
41		}
42		if err := api.RequireSecureURL(api.BaseURL()); err != nil {
43			return fmt.Errorf("base URL check: %w", err)
44		}
45		return nil
46	}
47	
48	// addInsecureHTTPAuthFlag attaches the hidden --insecure-http-auth flag used
49	// by every authenticated command for local development.
50	func addInsecureHTTPAuthFlag(cmd *cobra.Command, target *bool) {
51		cmd.Flags().BoolVar(target, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
52		if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
53			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
54		}
55	}
56	
57	func newAuthCmd() *cobra.Command {
58		cmd := &cobra.Command{
59			Use:   "auth",
60			Short: "Manage authentication and API tokens",
61			Long:  "Authentication subcommands. Includes login, logout, status, listing tokens, and revoking tokens.",
62			RunE: func(cmd *cobra.Command, _ []string) error {
63				return cmd.Help()
64			},
65		}
66	
67		cmd.AddCommand(newLoginCmd())
68		cmd.AddCommand(newLogoutCmd())
69		cmd.AddCommand(newAuthStatusCmd())
70		cmd.AddCommand(newAuthListCmd())
71		cmd.AddCommand(newAuthRevokeCmd())
72		return cmd
73	}
74	
75	// --- status -----------------------------------------------------------------
76	
77	func newAuthStatusCmd() *cobra.Command {
78		var insecureHTTPAuth bool
79		cmd := &cobra.Command{
80			Use:   "status",
81			Short: "Show authentication status",
82			RunE: func(cmd *cobra.Command, _ []string) error {
83				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
84					return err
85				}
86				return runAuthStatus(cmd.Context(), cmd.OutOrStdout(),
87					auth.NewStore(), defaultListTokens, api.BaseURL())
88			},
89		}
90		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
91		return cmd
92	}
93	
94	func defaultListTokens(ctx context.Context, token string) ([]api.Token, error) {
95		return api.NewClient(token).ListTokens(ctx) //nolint:wrapcheck // ListTokens already wraps with action context
96	}
97	
98	func runAuthStatus(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string) error {
99		info, err := store.GetTokenInfo(baseURL)
100		if err != nil {
101			return fmt.Errorf("read auth token: %w", err)
102		}
103		if info.Value == "" {
104			fmt.Fprintf(w, "Not logged in to %s\n", baseURL)
105			fmt.Fprintln(w, "Run 'entire login' to authenticate.")
106			return nil
107		}
108	
109		tokens, err := list(ctx, info.Value)
110		if err != nil {
111			if api.IsHTTPErrorStatus(err, http.StatusUnauthorized) {
112				fmt.Fprintf(w, "Token for %s is no longer valid.\n", baseURL)
113				if info.Source == auth.TokenSourceEnv {
114					fmt.Fprintf(w, "Update or unset %s to re-authenticate.\n", auth.AuthTokenEnvVar)
115				} else {
116					fmt.Fprintln(w, "Run 'entire login' to re-authenticate.")
117				}
118				return nil
119			}
120			return fmt.Errorf("validate token: %w", err)
121		}
122	
123		fmt.Fprintf(w, "Logged in to %s\n", baseURL)
124		fmt.Fprintf(w, "  Token: %s\n", describeTokenSource(info))
125		fmt.Fprintf(w, "  Active tokens on this account: %d\n", len(tokens))
126		return nil
127	}
128	
129	func describeTokenSource(info auth.TokenInfo) string {
130		switch info.Source {
131		case auth.TokenSourceNone:
132			return "not configured"
133		case auth.TokenSourceEnv:
134			return "supplied by " + auth.AuthTokenEnvVar
135		case auth.TokenSourceFile:
136			if info.Path != "" {
137				return "stored in file " + info.Path
138			}
139			return "stored in file"
140		case auth.TokenSourceKeyring:
141			return "stored in OS keychain"
142		default:
143			return "stored"
144		}
145	}
146	
147	// --- list -------------------------------------------------------------------
148	
149	func newAuthListCmd() *cobra.Command {
150		var jsonOut bool
151		var insecureHTTPAuth bool
152		cmd := &cobra.Command{
153			Use:   "list",
154			Short: "List active API tokens for the authenticated user",
155			RunE: func(cmd *cobra.Command, _ []string) error {
156				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
157					return err
158				}
159				return runAuthList(cmd.Context(), cmd.OutOrStdout(),
160					auth.NewStore(), defaultListTokens, api.BaseURL(), jsonOut)
161			},
162		}
163		cmd.Flags().BoolVar(&jsonOut, "json", false, "Print tokens as JSON")
164		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
165		return cmd
166	}
167	
168	func runAuthList(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string, jsonOut bool) error {
169		token, err := store.GetToken(baseURL)
170		if err != nil {
171			return fmt.Errorf("read auth token: %w", err)
172		}
173		if token == "" {
174			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
175		}
176	
177		tokens, err := list(ctx, token)
178		if err != nil {
179			return err
180		}
181	
182		if jsonOut {
183			enc := json.NewEncoder(w)
184			enc.SetIndent("", "  ")
185			if err := enc.Encode(tokens); err != nil {
186				return fmt.Errorf("encode JSON: %w", err)
187			}
188			return nil
189		}
190	
191		if len(tokens) == 0 {
192			fmt.Fprintln(w, "No active tokens.")
193			return nil
194		}
195	
196		// Deterministic order: most recently used first, then most recently
197		// created, then by id as a final tie-breaker so the output is fully
198		// specified regardless of the server's response order.
199		sort.Slice(tokens, func(i, j int) bool {
200			li := lastUsedSortKey(tokens[i])
201			lj := lastUsedSortKey(tokens[j])
202			if li != lj {
203				return li > lj
204			}
205			if tokens[i].CreatedAt != tokens[j].CreatedAt {
206				return tokens[i].CreatedAt > tokens[j].CreatedAt
207			}
208			return tokens[i].ID < tokens[j].ID
209		})
210	
211		sty := newAuthListStyles(w)
212		renderAuthListTable(w, sty, tokens, time.Now())
213		return nil
214	}
215	
216	// authListStyles holds the lipgloss styles for `entire auth list`. Mirrors the
217	// approach in activity_render.go: keep style construction tied to color
218	// detection, and render plain text when color is disabled.
219	type authListStyles struct {
220		colorEnabled bool
221	
222		header  lipgloss.Style // bold + dim, used for column headers
223		id      lipgloss.Style // yellow accent
224		name    lipgloss.Style // bold
225		value   lipgloss.Style // default fg for scope/dates (no color)
226		dim     lipgloss.Style // "never", "-"
227		warning lipgloss.Style // expires-soon
228		expired lipgloss.Style // already expired
229	}
230	
231	func newAuthListStyles(w io.Writer) authListStyles {
232		useColor := shouldUseColor(w)
233		s := authListStyles{colorEnabled: useColor}
234		if !useColor {
235			return s
236		}
237		s.header = lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true)
238		s.id = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
239		s.name = lipgloss.NewStyle().Bold(true)
240		s.value = lipgloss.NewStyle() // default fg
241		s.dim = lipgloss.NewStyle().Faint(true)
242		s.warning = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
243		s.expired = lipgloss.NewStyle().Foreground(lipgloss.Color("1")) // red
244		return s
245	}
246	
247	func (s authListStyles) render(style lipgloss.Style, text string) string {
248		if !s.colorEnabled {
249			return text
250		}
251		return style.Render(text)
252	}
253	
254	// renderAuthListTable prints a styled, column-aligned table of tokens. Column
255	// padding is computed via lipgloss.Width — it strips ANSI escapes, so a styled
256	// cell's visible width matches its plain text. tabwriter can't be used here
257	// once cells contain ANSI codes.
258	func renderAuthListTable(w io.Writer, sty authListStyles, tokens []api.Token, now time.Time) {
259		headerCells := []string{"ID", "NAME", "SCOPE", "CREATED", "LAST USED", "EXPIRES"}
260		header := make([]string, len(headerCells))
261		for i, h := range headerCells {
262			header[i] = sty.render(sty.header, h)
263		}
264	
265		rows := make([][]string, 0, len(tokens))
266		for _, t := range tokens {
267			rows = append(rows, []string{
268				sty.render(sty.id, t.ID),
269				styleName(sty, t.Name),
270				sty.render(sty.value, fallback(t.Scope, placeholderDash)),
271				sty.render(sty.value, formatAuthDate(t.CreatedAt)),
272				styleLastUsed(sty, t.LastUsedAt, now),
273				styleExpires(sty, t.ExpiresAt, now),
274			})
275		}
276	
277		widths := make([]int, len(headerCells))
278		for i, h := range header {
279			widths[i] = lipgloss.Width(h)
280		}
281		for _, row := range rows {
282			for i, c := range row {
283				if cw := lipgloss.Width(c); cw > widths[i] {
284					widths[i] = cw
285				}
286			}
287		}
288	
289		writeRow(w, header, widths)
290		for _, row := range rows {
291			writeRow(w, row, widths)
292		}
293	}
294	
295	func writeRow(w io.Writer, cells []string, widths []int) {
296		for i, c := range cells {
297			fmt.Fprint(w, c)
298			if i < len(cells)-1 {
299				fmt.Fprint(w, strings.Repeat(" ", widths[i]-lipgloss.Width(c)+2))
300			}
301		}
302		fmt.Fprintln(w)
303	}
304	
305	func styleName(sty authListStyles, name string) string {
306		if name == "" {
307			return sty.render(sty.dim, placeholderDash)
308		}
309		return sty.render(sty.name, name)
310	}
311	
312	func styleLastUsed(sty authListStyles, lastUsed *string, now time.Time) string {
313		if lastUsed == nil {
314			return sty.render(sty.dim, lastUsedNever)
315		}
316		return sty.render(sty.value, formatAuthLastUsed(lastUsed, now))
317	}
318	
319	func styleExpires(sty authListStyles, expiresAt string, now time.Time) string {
320		formatted := formatAuthDate(expiresAt)
321		switch classifyExpiresAt(expiresAt, now) {
322		case expiresExpired:
323			return sty.render(sty.expired, formatted)
324		case expiresSoon:
325			return sty.render(sty.warning, formatted)
326		case expiresNormal:
327			return sty.render(sty.value, formatted)
328		}
329		return sty.render(sty.value, formatted)
330	}
331	
332	func lastUsedSortKey(t api.Token) string {
333		if t.LastUsedAt == nil {
334			return ""
335		}
336		return *t.LastUsedAt
337	}
338	
339	// formatAuthDate renders an RFC3339 timestamp as YYYY-MM-DD in local time.
340	func formatAuthDate(s string) string {
341		if s == "" {
342			return placeholderDash
343		}
344		if ts, err := time.Parse(time.RFC3339, s); err == nil {
345			return ts.Local().Format("2006-01-02")
346		}
347		return s
348	}
349	
350	// formatAuthLastUsed renders a relative "last used" timestamp, with "yesterday"
351	// and absolute-date branches that the shared formatRelativeDuration helper
352	// doesn't cover.
353	func formatAuthLastUsed(s *string, now time.Time) string {
354		if s == nil || *s == "" {
355			return lastUsedNever
356		}
357		ts, err := time.Parse(time.RFC3339, *s)
358		if err != nil {
359			return *s
360		}
361		delta := now.Sub(ts)
362		switch {
363		case delta < 0, delta >= 30*24*time.Hour:
364			return ts.Local().Format("2006-01-02")
365		case delta >= 24*time.Hour && delta < 48*time.Hour:
366			return "yesterday"
367		default:
368			return formatRelativeDuration(delta)
369		}
370	}
371	
372	type expiresState int
373	
374	const (
375		expiresNormal expiresState = iota
376		expiresSoon
377		expiresExpired
378	)
379	
380	// classifyExpiresAt classifies an RFC3339 expires-at relative to now. Used to
381	// color the EXPIRES column so tokens worth rotating stand out.
382	func classifyExpiresAt(s string, now time.Time) expiresState {
383		if s == "" {
384			return expiresNormal
385		}
386		ts, err := time.Parse(time.RFC3339, s)
387		if err != nil {
388			return expiresNormal
389		}
390		delta := ts.Sub(now)
391		switch {
392		case delta <= 0:
393			return expiresExpired
394		case delta < 7*24*time.Hour:
395			return expiresSoon
396		default:
397			return expiresNormal
398		}
399	}
400	
401	func fallback(s, alt string) string {
402		if strings.TrimSpace(s) == "" {
403			return alt
404		}
405		return s
406	}
