410	func newAuthRevokeCmd() *cobra.Command {
411		var revokeCurrent bool
412		var insecureHTTPAuth bool
413		cmd := &cobra.Command{
414			Use:   "revoke [id]",
415			Short: "Revoke an API token by id",
416			Long:  "Revoke a specific API token. Use --current to revoke the token used by this CLI.",
417			Args:  cobra.MaximumNArgs(1),
418			RunE: func(cmd *cobra.Command, args []string) error {
419				id := ""
420				if len(args) == 1 {
421					id = args[0]
422				}
423				if id == "" && !revokeCurrent {
424					return cmd.Help()
425				}
426				if id != "" && revokeCurrent {
427					return errors.New("cannot use both <id> and --current")
428				}
429				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
430					return err
431				}
432				return runAuthRevoke(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(),
433					auth.NewStore(), defaultListTokens, defaultRevokeTokenByID, defaultRevokeCurrentToken,
434					api.BaseURL(), id, revokeCurrent)
435			},
436		}
437		cmd.Flags().BoolVar(&revokeCurrent, "current", false, "Revoke the token used by this CLI and remove the local copy when stored locally")
438		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
439		return cmd
440	}
441	
442	func defaultRevokeTokenByID(ctx context.Context, callerToken, id string) error {
443		return api.NewClient(callerToken).RevokeToken(ctx, id) //nolint:wrapcheck // RevokeToken already wraps with action context
444	}
445	
446	func runAuthRevoke(
447		ctx context.Context,
448		outW, errW io.Writer,
449		store tokenStore,
450		list authTokenLister,
451		revokeByID authTokenRevoker,
452		revokeCurrent revokeCurrentFunc,
453		baseURL, id string,
454		current bool,
455	) error {
456		info, err := store.GetTokenInfo(baseURL)
457		if err != nil {
458			return fmt.Errorf("read auth token: %w", err)
459		}
460		if info.Value == "" {
461			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
462		}
463	
464		if current {
465			return revokeCurrentToken(ctx, outW, errW, store, revokeCurrent, baseURL, info)
466		}
467	
468		if err := revokeByID(ctx, info.Value, id); err != nil {
469			return err
470		}
471	
472		// The list endpoint requires bearer auth, so a 401 here means the id we
473		// just revoked was the same one this CLI is using — the keychain entry is
474		// now stale and would otherwise produce confusing 401s on every command.
475		if _, listErr := list(ctx, info.Value); listErr != nil && api.IsHTTPErrorStatus(listErr, http.StatusUnauthorized) {
476			if info.Source == auth.TokenSourceEnv {
477				fmt.Fprintf(outW, "Revoked token %s (this was supplied by %s; unset it to stop using it locally).\n", id, auth.AuthTokenEnvVar)
478				return nil
479			}
480			if delErr := store.DeleteToken(baseURL); delErr != nil {
481				return fmt.Errorf("revoked token %s but failed to remove local copy: %w", id, delErr)
482			}
483			fmt.Fprintf(outW, "Revoked token %s (this was your local token; removed from %s).\n", id, localTokenSourceName(info))
484			return nil
485		}
486	
487		fmt.Fprintf(outW, "Revoked token %s.\n", id)
488		return nil
489	}
490	
491	func revokeCurrentToken(
492		ctx context.Context,
493		outW, errW io.Writer,
494		store tokenStore,
495		revoke revokeCurrentFunc,
496		baseURL string,
497		info auth.TokenInfo,
498	) error {
499		if info.Source == auth.TokenSourceEnv {
500			if err := revoke(ctx, info.Value); err != nil {
501				return fmt.Errorf("revoke current token: %w", err)
502			}
503			fmt.Fprintf(outW, "Revoked current token supplied by %s. Unset it to stop using it locally.\n", auth.AuthTokenEnvVar)
504			return nil
505		}
506	
507		if err := revoke(ctx, info.Value); err != nil && !api.IsHTTPErrorStatus(err, http.StatusUnauthorized) {
508			fmt.Fprintf(errW, "Warning: server-side token revocation failed: %v\n", err)
509		}
510		if err := store.DeleteToken(baseURL); err != nil {
511			return fmt.Errorf("remove auth token: %w", err)
512		}
513	
514		fmt.Fprintln(outW, "Logged out.")
515		return nil
516	}
517	
518	func localTokenSourceName(info auth.TokenInfo) string {
519		switch info.Source {
520		case auth.TokenSourceFile:
521			return "file"
522		case auth.TokenSourceKeyring:
523			return "keychain"
524		case auth.TokenSourceEnv:
525			return auth.AuthTokenEnvVar
526		case auth.TokenSourceNone:
527			return "local storage"
528		default:
529			return "local storage"
530		}
531	}
