21	const fallbackDeviceAuthPollInterval = time.Second
22	const defaultSlowDownBackoff = 5 * time.Second
23	const maxPollInterval = 30 * time.Second
24	const maxExpiresIn = 15 * time.Minute
25	const maxTransientErrors = 5
26	
