61	func runLoginWithStore(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc, store loginTokenStore) error {
62		start, err := client.StartDeviceAuth(ctx)
63		if err != nil {
64			return fmt.Errorf("start login: %w", err)
65		}
66	
67		fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
68	
69		approvalURL := start.VerificationURI
70	
71		if interactive.CanPromptInteractively() {
72			fmt.Fprintf(outW, "Press Enter to open %s in your browser and enter the generated device code...", approvalURL)
73	
74			// Read from /dev/tty so we get a real keypress and don't consume piped stdin.
75			if err := waitForEnter(ctx); err != nil {
76				return fmt.Errorf("wait for input: %w", err)
77			}
78	
79			fmt.Fprintln(outW)
80	
81			if err := openURL(ctx, approvalURL); err != nil {
82				fmt.Fprintf(errW, "Warning: failed to open browser: %v\n", err)
83				fmt.Fprintf(outW, "Open the approval URL in your browser to continue and enter the generated device code: %s\n", approvalURL)
84			}
85		} else {
86			fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
87		}
88	
89		fmt.Fprintln(outW, "Waiting for approval...")
90	
91		token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, time.Duration(start.Interval)*time.Second, defaultSlowDownBackoff)
92		if err != nil {
93			return fmt.Errorf("complete login: %w", err)
94		}
95	
96		if err := store.SaveToken(client.BaseURL(), token); err != nil {
97			if strings.TrimSpace(os.Getenv(auth.SecretsPathEnvVar)) == "" {
98				fmt.Fprintf(errW, "For headless environments, set %s=/path/to/credentials.json and retry `entire login`.\n", auth.SecretsPathEnvVar)
99			}
100			return fmt.Errorf("save auth token: %w", err)
101		}
102	
103		if strings.TrimSpace(os.Getenv(auth.AuthTokenEnvVar)) != "" {
104			fmt.Fprintf(errW, "Warning: %s is set and will take precedence over the newly saved login token until it is unset.\n", auth.AuthTokenEnvVar)
105		}
106	
107		fmt.Fprintln(outW, "Login complete.")
108		return nil
109	}
110	
111	func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (string, error) {
112		expiry := time.Duration(expiresIn) * time.Second
113		if expiry <= 0 || expiry > maxExpiresIn {
114			expiry = maxExpiresIn
115		}
116		deadline := time.Now().Add(expiry)
117		pollInterval := interval
118		if pollInterval <= 0 {
119			pollInterval = fallbackDeviceAuthPollInterval
120		}
121	
122		consecutiveErrors := 0
123	
124		for {
125			if time.Now().After(deadline) {
126				return "", errors.New("device authorization expired")
127			}
128	
129			result, err := poller.PollDeviceAuth(ctx, deviceCode)
130			if err != nil {
131				consecutiveErrors++
132				if consecutiveErrors >= maxTransientErrors {
133					return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
134				}
135				// Transient error — wait and retry.
136				select {
137				case <-ctx.Done():
138					return "", fmt.Errorf("wait for approval: %w", ctx.Err())
139				case <-time.After(pollInterval):
140				}
141				continue
142			}
143			consecutiveErrors = 0
144	
145			switch result.Error {
146			case "":
147				if result.AccessToken == "" {
148					return "", errors.New("device authorization completed without a token")
149				}
150				return result.AccessToken, nil
151			case "authorization_pending":
152				// no-op, will sleep and retry below
153			case "slow_down":
154				pollInterval += slowDownBackoff
155				if pollInterval > maxPollInterval {
156					pollInterval = maxPollInterval
157				}
158			case "access_denied":
159				return "", errors.New("device authorization denied")
160			case "expired_token":
161				return "", errors.New("device authorization expired")
162			default:
163				return "", fmt.Errorf("device authorization failed: %s", result.Error)
164			}
165	
166			select {
167			case <-ctx.Done():
168				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
169			case <-time.After(pollInterval):
170			}
171		}
172	}
173	
174	// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
175	// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
176	// Returns ctx.Err() if the context is cancelled before the user presses Enter.
177	func waitForEnter(ctx context.Context) error {
178		tty, err := os.Open("/dev/tty")
179		if err != nil {
180			return nil //nolint:nilerr // tty unavailable (e.g. Windows) — skip prompt silently
181		}
182	
183		done := make(chan error, 1)
184		go func() {
185			reader := bufio.NewReader(tty)
186			_, err := reader.ReadString('\n')
187			done <- err
188		}()
189	
190		select {
191		case <-ctx.Done():
192			// Close tty to unblock the reading goroutine.
193			_ = tty.Close()
194			return fmt.Errorf("interrupted: %w", ctx.Err())
195		case <-done:
196			_ = tty.Close()
197			return nil
198		}
199	}
200	
201	func openBrowser(ctx context.Context, browserURL string) error {
202		u, err := url.Parse(browserURL)
203		if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
204			return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
205		}
206	
207		var command string
208		var args []string
209	
210		switch runtime.GOOS {
211		case "darwin":
212			command = "open"
213			args = []string{browserURL}
214		case "linux":
215			command = "xdg-open"
216			args = []string{browserURL}
217		case "windows":
218			command = "cmd"
219			args = []string{"/c", "start", "", browserURL}
220		default:
221			return fmt.Errorf("unsupported platform %s", runtime.GOOS)
222		}
223	
224		cmd := exec.CommandContext(ctx, command, args...)
225		if err := cmd.Start(); err != nil {
226			return fmt.Errorf("start browser command %q: %w", command, err)
227		}
228	
229		if err := cmd.Process.Release(); err != nil {
230			return fmt.Errorf("release browser process: %w", err)
231		}
232	
233		return nil
234	}
