46			return auth.TokenInfo{}, m.getErr
47		}
48		token := m.tokens[baseURL]
49		if token == "" {
50			return auth.TokenInfo{}, nil
51		}
52		source := m.source
53		if source == auth.TokenSourceNone {
54			source = auth.TokenSourceKeyring
55		}
56		return auth.TokenInfo{Value: token, Source: source, Path: m.path}, nil
57	}
