// describeTokenSource is only called after runAuthStatus's empty-value early
// return, so info.Source is guaranteed to be one of the three real backends.
func describeTokenSource(info auth.TokenInfo) string {
	switch info.Source {
	case auth.TokenSourceEnv:
		return "supplied by " + auth.AuthTokenEnvVar
	case auth.TokenSourceFile:
		return "stored in file " + info.Path
	case auth.TokenSourceKeyring:
		return "stored in OS keychain"
	default:
		return "stored"
	}
}

// localTokenSourceName is only called from the by-id self-revoke 401 path,
// past the env-source early return — so source is guaranteed to be file or
// keyring (env tokens have no local copy to remove).
func localTokenSourceName(info auth.TokenInfo) string {
	if info.Source == auth.TokenSourceFile {
		return "file"
	}
	return "keychain"
}
